#!/usr/bin/env python3
"""Строит docs/ECONOMY_SIM.md из sim_results.json (+ таблица окладов из игры). Запуск: python3 tests/sim/report.py DIR"""
import json, sys, os, statistics as st, http.server, socketserver, threading, importlib.util
HERE = os.path.dirname(os.path.abspath(__file__)); ROOT = os.path.dirname(os.path.dirname(HERE))
DIR = sys.argv[1]; R = json.load(open(os.path.join(DIR, 'sim_results.json'), encoding='utf-8'))
spec = importlib.util.spec_from_file_location('rs', os.path.join(HERE, 'run_sim.py')); rs = importlib.util.module_from_spec(spec); spec.loader.exec_module(rs)
from playwright.sync_api import sync_playwright
def rub(x): return '{:,}'.format(int(round(x))).replace(',', ' ')
def med(a): return st.median(a) if a else 0
names = []
for r in R:
    if r['name'] not in names: names.append(r['name'])
def runs(n): return [r for r in R if r['name'] == n]
out = []
P = out.append
P('# Экономическая симуляция (Этап 2)\n')
P('Сгенерировано `tests/sim/run_sim.py` + `tests/sim/report.py`. Движок — **настоящие функции игры** (`G.endShift`, `G.payday`, `G.sleep`, `G.rollEvent`, `G.runAction`, банк) в Chromium, 3 seed на сценарий, 365 дней. Медиана по seed, если не сказано иное.\n')
P('**Допущения симулятора (честно):** утро/проходная пропускаются; на смене — операции, проверка чертежа, заводское молоко, подготовка к проверке по средам, перекус; еда и досуг — по сценарию из реальных цен `D.MENU`/`D.ITEMS`/`G.ACT`; окна событий решаются правилом «первый безопасный вариант, без взяток», экзамены сдаются с вероятностью 80% (реальные банки вопросов); отношения с NPC не моделируются (учитываются только траты и время). «Ступень» — `rank` игры (см. таблицу окладов ниже).\n')
P('## 1. Сводка по профилям: снимки на 30 / 90 / 180 / 365 день\n')
P('Деньги — наличные; «Долги» — долг + кредиты. Состояние: здоровье / энергия / настроение / сытость.\n')
P('| Профиль | День | Деньги | Долги | Ранг (смен) | Состояние |'); P('|---|---|---|---|---|---|')
for n in names:
    rr = [r for r in runs(n) if 'snaps' in r]
    for d in ('30', '90', '180', '365'):
        sn = [r['snaps'][d] for r in rr if d in r['snaps']]
        if not sn: P('| %s | %s | — (прервано: %s) | | | |' % (n, d, ','.join(sorted(set(str(r['ending']) for r in rr))))); continue
        P('| %s | %s | %s | %s | %s (%s) | %s/%s/%s/%s |' % (n if d == '30' else '', d, rub(med([x['money'] for x in sn])), rub(med([x['debt'] + x['loans'] for x in sn])), int(med([x['rank'] for x in sn])), int(med([x['shifts'] for x in sn])), int(med([x['hp'] for x in sn])), int(med([x['en'] for x in sn])), int(med([x['md'] for x in sn])), int(med([x['sat'] for x in sn]))))
P('')
P('Прерванные прогоны (концовка раньше 365-го дня): ' + (', '.join('%s seed%d → %s на дне %s' % (r['name'], r['seed'], r['ending'], r['endDay']) for r in R if r.get('ending')) or 'нет') + '\n')

def month_rows(r, only=None):
    rows = []
    for m in r['months']:
        if only and m['m'] not in only: continue
        i, o = m['in'], m['out']
        pay = i.get('выплата', 0); pw = i.get('сдельная', 0)
        other_in = sum(v for k, v in i.items() if k not in ('выплата', 'сдельная'))
        fixed = o.get('общага+связь+проезд', 0); ded = o.get('удержания (штрафы/долг)', 0)
        food = o.get('питание', 0) + o.get('питание вне дома', 0)
        disc = sum(v for k, v in o.items() if k in ('досуг', 'одежда', 'подарки', 'покупки', 'здоровье/быт', 'лечение'))
        fines = o.get('штрафы', 0)
        other = sum(v for k, v in o.items()) - fixed - ded - food - disc - fines
        tax = pay * 0.13 / 0.87
        e = m['end']
        rows.append('| %d | %s | %s | %s | %s | %s | %s | %s | %s | %s | %s | %s | %s/%s%s | %d/%d/%d |' % (m['m'], rub(pay), rub(pw), rub(other_in), rub(tax), rub(fixed), rub(food), rub(disc), rub(fines + ded + max(0, other)), rub(e['money']), rub(e['debt'] + e['loans']), rub(e['pay']), e['rank'], e['shifts'], '', m['hp'], m['md'], m['sat']))
    return rows
HDR = '| Мес. | Зарплата+аванс (на руки) | Сдельные | Прочие доходы | Налог 13% (оценка) | Общага/связь/проезд | Питание | Необяз. (досуг, вещи, подарки, здоровье) | Штрафы, удержания, прочее | Остаток | Долги | Оклад | Ранг/смен | Здор./настр./сыт. |'
SEP = '|' + '---|' * 14
P('## 2. Динамика по месяцам (месяц = 28 дней, seed 1)\n')
P('Налог посчитан как 13/87 от выплат на руки; аванс и расчёт сложены. «Остаток» — наличные на конец месяца.\n')
for n in names:
    r = [x for x in runs(n) if x['seed'] == 1 and 'months' in x][0]
    P('### ' + n + '\n'); P(HDR); P(SEP); [P(x) for x in month_rows(r)]; P('')
# ---- профессии × ранги
srv = rs.socketserver.TCPServer(('127.0.0.1', 0), rs.Q); port = srv.server_address[1]; threading.Thread(target=srv.serve_forever, daemon=True).start()
with sync_playwright() as pw:
    br = pw.chromium.launch(); ctx = br.new_context(); rs.install_routes(ctx); pg = ctx.new_page(); pg.goto('http://127.0.0.1:%d/index.html' % port); pg.wait_for_timeout(400)
    pays = pg.evaluate("""()=>{G.headless=true;const s=G.newState('T',{},G.D.EDU[0].id);const res=[];
      for(const id of Object.keys(G.D.JOBS)){const j=G.D.JOBS[id];const row=[id,j.name,j.harm];
        for(const r of [0,1,3,5,6,7,8,9,10]){s.car.job=id;s.car.rank=r;s.car.mgmtStage=1;try{row.push(Math.round(G.monthlyPay()));}catch(e){row.push(null);}}
        res.push(row);}return res;}""")
P('## 3. Оклады всех профессий по ступеням (брутто ₽/мес, из `G.monthlyPay`)\n')
P('Колонки: ранг 0 (стажёр), 1, 3, 5 (рабочие разряды), 6 Мастер, 7 Ст. мастер, 8 Зам. нач. цеха, 9 Нач. цеха, 10 Зам. ген. директора (ступень 1 управленческих ступеней).\n')
P('| Код | Профессия | Вред | 0 | р1 | р3 | р5 | 6 | 7 | 8 | 9 | 10 |'); P('|---|---|---|' + '---|' * 9)
for row in pays: P('| ' + ' | '.join(str(x if x is not None else '—') for x in row) + ' |')
P('')
# нормальная жизнь по рангам: берём профиль 2 (обычный) и профиль 8/7: средние месячные расходы на «нормальную жизнь» (еда+досуг+здоровье)
def avg_life(n):
    ms = [m for r in runs(n) if 'months' in r for m in r['months'] if m['m'] >= 2]
    f = [m['out'].get('питание', 0) + m['out'].get('питание вне дома', 0) for m in ms]
    d = [sum(v for k, v in m['out'].items() if k in ('досуг', 'одежда', 'подарки', 'покупки', 'здоровье/быт', 'лечение')) for m in ms]
    pw = [m['in'].get('сдельная', 0) for m in ms]
    return med(f), med(d), med(pw)
P('## 4. Сколько остаётся после нормальной жизни (профиль «Обычный игрок»)\n')
f, d, pw = avg_life('2 Обычный игрок')
P('Нормальная жизнь по симуляции: питание ≈ **%s ₽/мес**, досуг и бытовое ≈ **%s ₽/мес**, фиксированные вычеты 5 500 ₽, сдельная прибавка за операции ≈ **%s ₽/мес** (растёт с рангом). Остаток = оклад×0.87 + сдельные − 5 500 − питание − досуг.\n' % (rub(f), rub(d), rub(pw)))
P('| Ступень | Оклад брутто | На руки | + сдельные (оценка) | − фикс. | − нормальная жизнь | **Остаётся** | В % от на руки |'); P('|---|---|---|---|---|---|---|---|')
pw_by_rank = {}
for r in R:
    for m in r.get('months', []):
        pw_by_rank.setdefault(m['end']['rank'], []).append(m['in'].get('сдельная', 0))
def pwr(rk):
    ks = [k for k in pw_by_rank if k <= rk]; k = max(ks) if ks else min(pw_by_rank)
    return med(pw_by_rank[k])
def line(lbl, gross, rk):
    net = gross * 0.87; pwv = pwr(rk); rest = net + pwv - 5500 - f - d
    return '| %s | %s | %s | %s | 5 500 | %s | **%s** | %d%% |' % (lbl, rub(gross), rub(net), rub(pwv), rub(f + d), rub(rest), round(100 * rest / max(1, net + pwv)))
colidx = {1: 4, 3: 5, 5: 6, 6: 7, 7: 8, 8: 9, 9: 10, 10: 11}
for jid, jn in (('podsob', 'Подсобный'), ('tokar', 'Токарь'), ('svarshik', 'Сварщик'), ('plavilshik', 'Плавильщик'), ('deloproizv', 'Делопроизводитель')):
    row = [r for r in pays if r[0] == jid][0]
    for rk, lb in ((1, 'р1'), (3, 'р3'), (5, 'р5')): P(line(jn + ' ' + lb, row[colidx[rk]], rk))
mg = [r for r in pays if r[0] == 'podsob'][0]
for rk, lb in ((6, 'Мастер участка'), (7, 'Старший мастер'), (8, 'Зам. нач. цеха'), (9, 'Начальник цеха'), (10, 'Зам. ген. директора')): P(line('**' + lb + '**', mg[colidx[rk]], rk))
best5 = max(r[6] for r in pays)
P('\nЛучший рабочий оклад р5 в игре — **%s ₽** (%s); Мастер участка получает **%s ₽** — разница %+d%%.\n' % (rub(best5), [r[1] for r in pays if r[6] == best5][0], rub(mg[7]), round(100 * (mg[7] - best5) / best5)))
P('')

# ---- источники начисления
P('## 5. Откуда берутся деньги в зарплатной ведомости (365 дней, seed 1)\n')
P('Измерено перехватом `s.pay.acc` (накопленное за месяц до удержания 13%). «Начисление за смены» — оклад/20 × качество за смену (`engine.js:474`).\n')
P('| Профиль | За смены | Премия завода «+3 000 ₽ каждый понедельник» | События (поручения, награды) | Надбавки v38 | Итого | Доля «премии завода» |'); P('|---|---|---|---|---|---|---|')
for n in names:
    rr = [r for r in runs(n) if r['seed'] == 1 and r.get('acc')]
    if not rr: continue
    acc = rr[0]['acc']; g = lambda key: sum(v[1] for k, v in acc.items() if key in k)
    sh, pl_, ev, v38 = g('engine.js:474'), g('plantDaily'), g('engine.js:403'), g('v38.js')
    tot = sum(v[1] for v in acc.values())
    P('| %s | %s | %s | %s | %s | %s | %d%% |' % (n, rub(sh), rub(pl_), rub(ev), rub(v38), rub(tot), round(100 * pl_ / max(1, tot))))
P('')
# ---- предприятие
cp = os.path.join(DIR, 'ceo_results.json')
P('## 6. Профиль 9: управление предприятием (365 дней, пассивное управление)\n')
P('**Ограничение:** симулятор назначает директора через dev-вход `G.ceo.dev.now()` и решает события компании первым вариантом, **не управляя** производством, закупками, продажами и кадрами. Это проверка устойчивости режима «ничего не делать», а не баланс «умелого» директора; баланс компании требует политики управления (Этап 3–4).\n')
if os.path.exists(cp):
    C = json.load(open(cp, encoding='utf-8'))
    P('| Сложность | День | Личные деньги | Оклад | Казна | Доверие совета | Прибыль (отчёт) |'); P('|---|---|---|---|---|---|---|')
    for c in C:
        if 'rows' not in c: P('| %s | ошибка: %s | | | | | |' % (c['diff'], c.get('error'))); continue
        for rw in c['rows'][::4]:
            P('| %s | %d | %s | %s | %s | %s | %s |' % (c['diff'], rw['day'], rub(rw['personal']), rub(rw['pay']), rub(rw['treasury']), rw['trust'], rub(rw['profit'] or 0)))
    P('\nКонцовки за год: ' + ', '.join('%s → %s' % (c['diff'], c.get('ending')) for c in C) + '.\n')

# ---- премия завода: когда сработала бы концовка «prosper»
pd_ = [r['stats'].get('prosperDay') for r in R if r.get('stats') and r['kind'] == 'base']
pd_ = [x for x in pd_ if x]
P('## 7. Выводы Этапа 2\n')
P('**Концовка «ЗАВОД ПРОЦВЕТАЕТ» (`data_actions.js:1219`)** без требований к должности: в симуляции она сработала бы в %d из %d базовых прогонов, медиана — на %s-й день (стажёр/р3). В симуляторе она подавлена, чтобы считать экономику дальше.\n' % (len(pd_), len([r for r in R if r.get('stats') and r['kind'] == 'base']), int(med(pd_)) if pd_ else '—'))
P('1. **Начало игры слишком лёгкое.** Даже «много тратит на еду и вещи» остаётся в плюсе весь год. Причина — не оклад, а три добавки: «премия завода» +3 000 ₽ в каждый понедельник (≈25% всех начислений новичка, ≈13 000 ₽/мес при окладе стажёра 12 000), сдельные за операции (3–12 тыс./мес) и стартовые награды. Целевое ощущение «трудно, но не безнадёжно» достигается, если у новичка на нормальной жизни остаётся около нуля–5 тыс. ₽, а у экономного 8–12 тыс.')
P('2. **Разрыв оклад рабочего / руководителя не работает** (раздел 4): Плавильщик р5 получает больше Мастера участка; Токарь р5 почти равен Мастеру. Руководящие ступени не зависят от профессии, поэтому для «вредных» профессий повышение в мастера — снижение дохода.')
P('3. **Богатство обесценивает экономику.** Через год: новичок-эконом ≈ 520 тыс., обычный ≈ 380 тыс., руководитель ≈ 1,1 млн. Гранта (350 тыс.) покупается за 10–11 месяцев экономом, а руководитель с её ценой не считается. Вторых целей, куда деньги реально уходят, нет.')
P('4. **Ловушка штрафов.** Брак: штраф «лишение премии» до 6 000 ₽ за смену (`data_actions.js:1519`), но он вычитается из всей выплаты, без потолка. При плохой работе (сценарий В) выплата уходит в минус, создаётся долг 52 тыс. в первый месяц и ~940 тыс. к концу года, из которого нет выхода (оклад 17 тыс.). Сценарий Д («всё сразу») даёт долг 70–150 тыс. Нужен потолок удержаний (не больше доли начисления) и отсутствие отрицательных выплат.')
P('5. **Питание — не проблема, но наказание за пропуск жёсткое.** Нормальное питание ≈ 3 100 ₽/мес, потому что «Сварить макароны» бесплатно (`cook`, +28 сытости раз в день вечером). Зато если пропустить любую еду на 24 часа, настроение падает до 6 одним скачком (`v34.js`), а повторы ведут к потере здоровья и концовке «увольнение/здоровье». Пропущенный обед из-за события ≥ 2 часов (обед только в окне 12:00–13:00) — частая ситуация (в сценарии «Эконом» 1 день без обеда за год, но шаблон отмечен).')
P('6. **Кредиты в симуляции переживаются только из-за избытка доходов** (п. 1). Кредит 50 000 ₽ под 38% гасится платежами 4 800 ₽ и закрыт к концу года; микрозайм 5 000 ₽ (1,5%/день) за ~18 дней превращается в ≈ 6 500 ₽ (переплата ≈ 30%); сценарий Г (50 000 + 200 000 под 42% + три микрозайма) за год не обанкротил игрока, но к 365-му дню остаток кредитов ≈ 33 500 ₽ при деньгах 459 тыс., то есть игрок мог бы закрыть всё сразу. После выравнивания доходов кредиты нужно перепроверить; ипотеку (платёж = процентам) в сценариях не брали намеренно, она нерабочая по расчёту (см. аудит).')
P('7. **Болезнь** (7 дней в месяц) замедляет карьеру вдвое (ранг 6 вместо 7 за год), здоровье падает до 30. Штрафы 1 500 ₽/мес почти не влияют. Это нормальное поведение.')
P('8. **Предприятие.** При пассивном управлении компания убыточна, доверие совета падает до 2 и не приводит к отставке, а оклад 300 000 ₽ продолжает выплачиваться. Баланс режима нельзя оценить без политики управления — Этап 3–4.\n')
P('## 8. Предварительные значения для Этапа 3 (на согласование, после правок будет повторный прогон)\n')
P('| Параметр | Сейчас | Предлагается | Зачем |'); P('|---|---|---|---|')
P('| Премия завода за план | +3 000 ₽/нед всем | 5% оклада ступени в неделю (мин. 500), только при выполнении плана | Не должна быть главной частью дохода новичка |')
P('| Удержания по штрафам | до 6 000 ₽/смена, без потолка | не более 20% начисления за месяц; выплата не может быть отрицательной | Убрать долговую спираль |')
P('| «Завод процветает» | любой ранг, ~45 смен | требует ранг ≥ 8 и 8 недель подряд | Не обрывать игру на р3 |')
P('| Оклад Мастера участка | 38–45 тыс. | 60–70 тыс. (≥ +25% к лучшему р5) | Повышение должно ощущаться |')
P('| Старший мастер / Зам. нач. цеха / Нач. цеха / Зам. ген. | 52–62 / 75–85 / 90–110 / 180–200 тыс. | 80–92 / 105–125 / 150–175 / 230–260 тыс. | Плавная лестница, без разрыва ×2 на последней ступени |')
P('| Вредность | ×1.12 на всех ступенях | фиксированная надбавка по классу вредности, не растёт на руководящих | Плавильщик не должен обгонять мастера |')
P('| Фиксированные расходы | 5 500 ₽ всем | жильё по ступени: общага 3 500 → съём 9 000 (р4+) → квартира 20 000+ (Ст. мастер+, по желанию); связь 500 → 1 000; проезд/авто — выбор | Расходы растут вместе с уровнем жизни, но остаются решением игрока |')
P('| Сдельные за операции | на всех рангах | убрать у руководящих (ранг ≥ 6), заменить решениями участка | Руководитель не точит детали |')
P('| Стартовая подушка | 3 000 ₽ | оставить | Проверить после выравнивания |')
P('| Кредиты/ипотека/микрозайм | см. аудит | аннуитет, график платежей, пени, реструктуризация, лимит по доходу | Согласовано |')

json.dump(dict(pays=pays), open(os.path.join(DIR, 'pays.json'), 'w'))
open(os.path.join(ROOT, 'docs', 'ECONOMY_SIM.md'), 'w', encoding='utf-8').write('\n'.join(out))
print('written', len(out), 'lines')

